CREATE TABLE "credit_ledger_archive" (
	"id" uuid PRIMARY KEY NOT NULL,
	"user_hash" text NOT NULL,
	"delta" integer NOT NULL,
	"reason" "credit_reason" NOT NULL,
	"application_id" uuid,
	"stripe_invoice_id" text,
	"note" text,
	"created_at" timestamp with time zone NOT NULL,
	"archived_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "credit_ledger_archive_hash_ck" CHECK (user_hash ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
CREATE TABLE "deletion_tasks" (
	"user_hash" text PRIMARY KEY NOT NULL,
	"email_hash" text NOT NULL,
	"requested_by" text NOT NULL,
	"requested_at" timestamp with time zone DEFAULT now() NOT NULL,
	"storage_id" text,
	"stripe_customer_id" text,
	"stripe_customer_hash" text,
	"tombstone_written_at" timestamp with time zone,
	"stripe_done_at" timestamp with time zone,
	"verified_at" timestamp with time zone,
	"r2_done_at" timestamp with time zone,
	"audit_pseudonymised_at" timestamp with time zone,
	"llm_scrubbed_at" timestamp with time zone,
	"completed_at" timestamp with time zone,
	"attempts" integer DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_error_code" text,
	"paged_at" timestamp with time zone,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "deletion_tasks_hash_ck" CHECK (user_hash ~ '^[0-9a-f]{64}$' AND email_hash ~ '^[0-9a-f]{64}$' AND (stripe_customer_hash IS NULL OR stripe_customer_hash ~ '^[0-9a-f]{64}$')),
	CONSTRAINT "deletion_tasks_audit_ck" CHECK (verified_at IS NULL OR audit_pseudonymised_at IS NOT NULL),
	CONSTRAINT "deletion_tasks_by_ck" CHECK (requested_by IN ('user','operator','replay')),
	CONSTRAINT "deletion_tasks_r2_ck" CHECK (r2_done_at IS NULL OR (storage_id IS NULL AND verified_at IS NOT NULL)),
	CONSTRAINT "deletion_tasks_stripe_ck" CHECK (stripe_done_at IS NULL OR stripe_customer_id IS NULL),
	CONSTRAINT "deletion_tasks_complete_ck" CHECK (completed_at IS NULL OR (tombstone_written_at IS NOT NULL AND stripe_done_at IS NOT NULL AND verified_at IS NOT NULL
        AND r2_done_at IS NOT NULL AND llm_scrubbed_at IS NOT NULL AND audit_pseudonymised_at IS NOT NULL)),
	CONSTRAINT "deletion_tasks_error_ck" CHECK (last_error_code IS NULL OR last_error_code ~ '^[a-z0-9_]{1,64}$')
);
