-- The pseudonym written by the erasure worker (jobs/erasure.ts) must be that of an existing deletion task, so the
-- worker's UPDATE (actor) grant cannot forge one (Security-reviewer and DB-reviewer, WP-25 round 1 and 2).
CREATE OR REPLACE FUNCTION ops_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  -- The one allowed update (extend here, nothing else): actor of a deleted user becomes an erased:<32 hex> pseudonym.
  IF TG_OP = 'UPDATE'
     AND NEW.actor ~ '^erased:[0-9a-f]{32}$' AND OLD.actor !~ '^erased:'
     AND OLD.actor !~ '^system:'
     AND NOT EXISTS (SELECT 1 FROM "user" WHERE id = OLD.actor)
     AND EXISTS (SELECT 1 FROM deletion_tasks d WHERE left(d.user_hash, 32) = substr(NEW.actor, 8))
     AND (NEW.id, NEW.at, NEW.action, NEW.target, NEW.before, NEW.after)
         IS NOT DISTINCT FROM (OLD.id, OLD.at, OLD.action, OLD.target, OLD.before, OLD.after)
  THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'ops_audit is append-only (% blocked)', TG_OP USING ERRCODE = '42501';
END $$;
